$_MODULE['<{amazonmarketplacepro}prestashop>configure_f9f2d03af364aa656f60472f050f5ce9'] = 'Amazon presenta un pagamento in corso come ordine «Pending». Con questa opzione il modulo toglie subito quelle unità dalla giacenza PrestaShop, così nessun altro canale può venderle, e le restituisce se l\'ordine non diventa mai pagabile. Richiede l\'importazione degli ordini Pending — il modulo la esegue automaticamente una volta attivata l\'opzione — e il cron remote_cart per chiudere le riserve.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_606e569ed905da68a3f26de02575c6d9'] = 'Rilascia una riserva dopo';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4e9a4f12657cf4a16631d3bfbbd3ea93'] = 'Periodo di tolleranza prima che la giacenza di un ordine ancora fermo in Pending venga restituita. 4 ore è un valore sicuro: Amazon può metterci un po\' a portare un ordine in Unshipped.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_a2d4829bd7afcb0622263a02a3b7a5fc'] = 'Ordini senza giacenza sufficiente';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_64f05d6bfbce6140c765c29e952478b7'] = 'Crea comunque l\'ordine PS';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9d7f6ecb0a0a1a38c076bc7a432c4907'] = 'Metti in Ordini in sospeso per la revisione manuale';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_dacbbee8d1ca69a51619dc28dcd68e21'] = 'Se attiva, gli ordini preparati i cui prodotti non hanno giacenza (e non sono ordinabili in esaurimento) restano nella scheda Ordini in sospeso invece di diventare ordini PS.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_7a8156b022b1920dc000a4274b89a638'] = 'Corriere predefinito';
