$_MODULE['<{amazonmarketplacepro}prestashop>configure_5cbc8ff529ecab618089ef063e3be9d2'] = 'Amazon comunica la velocità di consegna promessa all\'acquirente. Associa ciascuna a un corriere PrestaShop affinché gli ordini importati riportino il metodo di spedizione corretto; quelle senza corrispondenza useranno il corriere predefinito qui sopra.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9fd1338f1dd68b2455075cc183be657f'] = 'Velocità di spedizione Amazon';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_15f87e0fa572c90443e2c0dc75d66819'] = '-- Corriere predefinito --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4fb6f1cf6de6ffac53ce3a98e1263f7a'] = 'Regole di stato avanzate';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_1eb7e0300a389884bba094f84a1dfce1'] = 'Assegna a determinati tipi di ordine un proprio stato PrestaShop: per esempio gli ordini Prime in uno stato ben visibile che il magazzino non possa mancare, o gli ordini FBA direttamente in Spedito. Le regole vengono valutate dall\'alto verso il basso e vince la prima corrispondenza; «Qualsiasi» ignora quel criterio. Una regola senza stato viene saltata.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_be7938e9a87618a98a7b6b47e12aa44b'] = 'Prime';
