$_MODULE['<{amazonmarketplacepro}prestashop>configure_3f4f37feac232d245ca3044c7707bdf5'] = 'Esporta tutti i prodotti e le combinazioni, correggi riferimenti e codici a barre in un foglio di calcolo, poi ricarica il file. Vengono scritti solo riferimento, EAN, UPC e riferimento fornitore; le colonne chiave e nome sono di sola lettura.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_d334670c5c0ccd4279522bca993b7da2'] = 'Questa operazione modifica direttamente il tuo catalogo PrestaShop e non può essere annullata: fai prima un backup del database. Ad Amazon non viene inviato nulla. Eseguila prima di pubblicare, altrimenti creerai SKU duplicati su Amazon.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c04f1e4841a6af78088d6ccf6f3a8a76'] = 'Esporta CSV';
