$_MODULE['<{amazonmarketplacepro}prestashop>configure_79f1b4c3c4edb48dd3bae5325b2ae846'] = 'Rimuove da Amazon le offerte dei prodotti che non vendi più: eliminati, disattivati o esclusi da Amazon nella scheda prodotto. Esamina prima l\'elenco: l\'eliminazione cancella l\'offerta e la sua cronologia su Amazon, e non è reversibile da qui.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_2d0e5660bea8a218a576ac7526dad77b'] = 'Se vuoi solo sospendere temporaneamente la vendita, pubblicare la quantità 0 (valori predefiniti delle inserzioni) mantiene attiva l\'inserzione e le sue recensioni.';
