$_MODULE['<{amazonmarketplacepro}prestashop>configure_c60fbb93366c2db82e7f15b891519249'] = 'Invia ciò che il confronto segnala come in attesa. Fino a 25 SKU partono uno per uno e ricevono risposta immediata; oltre, l\'invio avviene con un unico feed, che segui in Stato del feed.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_3110cdebee6849c61252bfb7860c2700'] = 'Amazon → PrestaShop';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_123999c78f3b0fb3c2882359df62183a'] = 'Porta le inserzioni Amazon in PrestaShop. Il primo passaggio si limita a leggere e confrontare; nel secondo scegli cosa scrivere, dopo aver guardato la tabella.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_7a39a1aacfcb9ac0960364ad6017a5ce'] = 'Sincronizza Amazon verso PS';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_ac2360e03b18358b7be754f743139fed'] = 'Legge le tue inserzioni Amazon e segnala, SKU per SKU, ciò che manca a PrestaShop o che vi è memorizzato diversamente. Il confronto compare qui sotto. In PrestaShop non viene ancora scritto nulla.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_35ed5077b53753fe6892726329a04f98'] = 'Scegli cosa fare del confronto. A crea ciò che manca a PrestaShop; B modifica ciò che è già presente.';
