$_MODULE['<{amazonmarketplacepro}prestashop>configure_3827a19c1cab90f7baec0f76c4750697'] = 'I prodotti presenti su Amazon ma assenti in PrestaShop vengono creati come prodotti NON ATTIVI (titolo, descrizione, marca, prezzo, giacenza, immagini) nella categoria scelta, per la revisione. I prezzi sono importati senza gruppo di imposte: assegnane uno prima di attivarli.';
