$_MODULE['<{amazonmarketplacepro}prestashop>configure_9be5c35a00a021a4768162f65558fc35'] = 'Per i prodotti presenti in entrambi i cataloghi, sovrascrive in PrestaShop i campi selezionati con i valori di Amazon. Ogni campo è indipendente: seleziona solo ciò che vuoi sovrascrivere. L\'operazione non è annullabile, quindi fai prima un backup. I prezzi arrivano IVA inclusa e vengono convertiti usando la regola fiscale di ciascun prodotto.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_f09455b329365f7fdf49ea763abc10d0'] = 'Stato del feed';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_de64a1d2acd922dc141be655d48fa0c0'] = 'Un invio di più di 25 SKU arriva ad Amazon come un unico documento feed, che Amazon elabora in background anziché rispondere subito. Controlla qui se è terminato e che cosa è stato rifiutato. Gli invii più piccoli ricevono risposta immediata sotto il pulsante di invio.';
